program main;

{ The program runs from begin to the final end with a full stop. }
begin
  WriteLn('Hello, world!');
  WriteLn('Welcome to Pascal.');

  // Write stays on the same line; WriteLn moves to the next one.
  Write('Two plus three is ');
  WriteLn(2 + 3);

  // Several values, separated by commas, in one WriteLn.
  WriteLn('A week has ', 7 * 24, ' hours.');
  WriteLn;
  WriteLn('Goodbye!');
end.

program main;

// Every variable is declared in the var block, with its type.
var
  shop: String;
  shirts: Integer;
  price: Double;
  size: Char;
  inStock: Boolean;

begin
  // := gives a variable its value.
  shop := 'Corner Shop';
  shirts := 3;
  price := 12.5;
  size := 'M';
  inStock := True;

  WriteLn('Shop: ', shop);
  WriteLn('T-shirts: ', shirts, ' in size ', size);
  WriteLn('In stock? ', inStock);
  WriteLn('Price: ', price);

  // A variable can change, but always keeps its type.
  shirts := shirts + 2;
  WriteLn('T-shirts after the delivery: ', shirts);
  WriteLn('Value of the stock: ', shirts * price:0:2);
  WriteLn('Largest Integer: ', High(Integer));
end.

program main;

var
  minutes, slices, friends: Integer;
  share: Double;

begin
  // div divides whole numbers; mod gives the remainder.
  minutes := 135;
  WriteLn(minutes, ' min = ', minutes div 60, ' h ', minutes mod 60, ' min');

  slices := 17;
  friends := 5;
  WriteLn('Each friend gets ', slices div friends, ' slices');
  WriteLn('Slices left over: ', slices mod friends);

  // / always gives a real number, even with two integers.
  share := slices / friends;
  WriteLn('Exact share: ', share:0:2);

  // * and / go before + and -; brackets change the order.
  WriteLn('2 + 3 * 4 = ', 2 + 3 * 4);
  WriteLn('(2 + 3) * 4 = ', (2 + 3) * 4);

  // From real to integer: Trunc cuts, Round rounds.
  WriteLn('Trunc(3.7) = ', Trunc(3.7), ' | Round(3.7) = ', Round(3.7));
  // Round sends .5 to the even number.
  WriteLn('Round(2.5) = ', Round(2.5), ' | Round(3.5) = ', Round(3.5));
  WriteLn('Even? ', 42 mod 2 = 0);
end.

program main;

uses
  SysUtils;

var
  price: Double;

begin
  price := 3.456;
  // With no format, a real number comes out in scientific notation.
  WriteLn(price);
  // :0:2 means as wide as needed, with two decimals.
  WriteLn(price:0:2);
  // :8:2 fills up to 8 characters, aligned to the right.
  WriteLn('[', price:8:2, ']');
  WriteLn('[', 42:6, ']', '[', 'tea':6, ']');

  // Format, from SysUtils, builds a string from a pattern.
  WriteLn(Format('%-10s%4s%9s', ['Item', 'Qty', 'Euros']));
  WriteLn(Format('%-10s%4d%9.2f', ['Coffee', 2, 2.40]));
  WriteLn(Format('%-10s%4d%9.2f', ['Croissant', 3, 4.65]));
  WriteLn(Format('%-10s%4d%9.2f', ['Juice', 1, 2.10]));
  WriteLn(Format('%-14s%9.2f', ['Total', 9.15]));
  WriteLn(Format('VAT included: %d%%', [10]));
end.

program main;

var
  name: String;
  age, tickets, first, second: Integer;
  price: Double;

begin
  Write('What is your name? ');
  ReadLn(name);
  WriteLn('Nice to meet you, ', name, '!');

  // ReadLn turns the text into the type of the variable.
  Write('How old are you? ');
  ReadLn(age);
  WriteLn('In 10 years you will be ', age + 10, '.');

  Write('Price of a cinema ticket? ');
  ReadLn(price);
  Write('How many tickets? ');
  ReadLn(tickets);
  WriteLn(tickets, ' tickets cost ', price * tickets:0:2, ' euros.');

  // Several numbers on the same line, separated by spaces.
  Write('Your two exam marks? ');
  ReadLn(first, second);
  WriteLn('Average mark: ', (first + second) / 2:0:1);
end.

program main;

var
  temp, grade: Integer;

begin
  temp := 31;
  // The line after then only runs if the condition is true.
  if temp > 30 then
    WriteLn(temp, ' C: it is hot, drink water.');
  if temp < 10 then
    WriteLn('Take a coat.');

  // Several statements go between begin and end.
  // There is never a semicolon just before else.
  grade := 6;
  if grade >= 5 then
  begin
    WriteLn('Grade ', grade, ': passed.');
    WriteLn('See you next year.');
  end
  else
    WriteLn('Grade ', grade, ': failed.');

  // else if checks the conditions in order.
  if grade >= 9 then
    WriteLn('Outstanding')
  else if grade >= 7 then
    WriteLn('Very good')
  else if grade >= 5 then
    WriteLn('Pass')
  else
    WriteLn('Fail');
end.

program main;

var
  day, score: Integer;
  option: Char;

begin
  day := 6;
  case day of
    1..5: WriteLn('Day ', day, ': working day');
    6, 7: WriteLn('Day ', day, ': weekend');
  else
    WriteLn('Day ', day, ': not a day of the week');
  end;

  // Ranges keep a grade table short.
  score := 83;
  case score of
    90..100: WriteLn(score, ' points: A');
    80..89: WriteLn(score, ' points: B');
    70..79: WriteLn(score, ' points: C');
  else
    WriteLn(score, ' points: keep practising');
  end;

  // case also works with Char: a vending machine.
  option := 'b';
  case option of
    'a': WriteLn('Water: 1.00');
    'b': WriteLn('Coffee: 1.50');
    'c': WriteLn('Juice: 2.00');
  end;
end.

program main;

var
  age, height: Integer;
  hasTicket, isMember, canRide, discount: Boolean;

begin
  age := 12;
  height := 145;
  hasTicket := True;
  isMember := False;

  // = compares (:= assigns) and <> means "not equal".
  WriteLn('Is the age 12? ', age = 12);
  WriteLn('Is the age not 18? ', age <> 18);
  WriteLn('Taller than 1.50 m? ', height > 150);

  // With and/or, each comparison goes in its own brackets.
  canRide := (height >= 140) and hasTicket;
  WriteLn('Can ride the roller coaster? ', canRide);

  discount := (age < 14) or (age >= 65) or isMember;
  WriteLn('Gets a discount? ', discount);
  WriteLn('Pays full price? ', not discount);

  // xor is true when exactly one side is true.
  WriteLn('Ticket or card, but not both? ', hasTicket xor isMember);

  if (age >= 10) and (age <= 12) then
    WriteLn('Category: junior');
end.

program main;

var
  savings, weeks, bounces: Integer;
  height: Double;

begin
  // while checks the condition before each turn.
  savings := 0;
  weeks := 0;
  while savings < 100 do
  begin
    savings := savings + 15;
    weeks := weeks + 1;
  end;
  WriteLn('After ', weeks, ' weeks: ', savings, ' euros saved');

  // repeat runs at least once and stops when until is true.
  height := 8.0;
  bounces := 0;
  repeat
    height := height / 2;
    Inc(bounces);  // the same as bounces := bounces + 1
    WriteLn('Bounce ', bounces, ': ', height:0:2, ' m');
  until height < 1;

  // A while loop whose condition is false never runs.
  while savings < 50 do
    WriteLn('This line never appears.');
  WriteLn('Done.');
end.

program main;

var
  i, total: Integer;
  c: Char;

begin
  // for ... to counts up, one at a time.
  for i := 1 to 5 do
    WriteLn('7 x ', i, ' = ', 7 * i);

  // downto counts down.
  for i := 3 downto 1 do
    Write(i, '... ');
  WriteLn('Lift-off!');

  // Add up the odd numbers from 1 to 99.
  total := 0;
  for i := 1 to 99 do
    if i mod 2 = 1 then
      total := total + i;
  WriteLn('Odd numbers up to 99 add up to ', total);

  // The counter can also be a Char: a grid of cinema seats.
  for i := 1 to 3 do
  begin
    Write('Row ', i, ':');
    for c := 'A' to 'E' do
      Write(' ', i, c);
    WriteLn;
  end;
end.

program main;

// A constant array: the names of the days.
const
  Days: array[1..7] of String = ('Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun');

// A variable array of 7 integers, with initial values.
var
  temps: array[1..7] of Integer = (18, 21, 24, 19, 26, 28, 22);
  i, hottest, total: Integer;

begin
  temps[4] := 20;  // change one element
  total := 0;
  hottest := 1;
  // Low and High give the first and last index.
  for i := Low(temps) to High(temps) do
  begin
    WriteLn(Days[i], ': ', temps[i]:3, ' C');
    total := total + temps[i];
    if temps[i] > temps[hottest] then
      hottest := i;
  end;
  WriteLn('Average: ', total / Length(temps):0:1, ' C');
  WriteLn('Hottest day: ', Days[hottest], ' (', temps[hottest], ' C)');
end.

program main;

uses
  SysUtils;

var
  first, last, full, email, user, domain: String;
  at: Integer;

begin
  first := 'Ada';
  last := 'Lovelace';
  // + joins strings.
  full := first + ' ' + last;
  WriteLn('Full name: ', full, ' (', Length(full), ' characters)');

  // Characters are numbered from 1.
  WriteLn('Initials: ', first[1], last[1]);
  WriteLn('In capitals: ', UpperCase(full));
  WriteLn('In small letters: ', LowerCase(full));

  // Pos finds a piece of text; Copy(s, start, count) cuts one out.
  email := 'ada.lovelace@example.com';
  at := Pos('@', email);
  user := Copy(email, 1, at - 1);
  domain := Copy(email, at + 1, Length(email) - at);
  WriteLn('The @ is at position ', at);
  WriteLn('User: ', user, ' | Domain: ', domain);
  WriteLn('Position of "xyz": ', Pos('xyz', email));

  // IntToStr turns a number into text, ready to join.
  WriteLn('Order ' + IntToStr(1024) + ' for ' + first);
end.

