// A function returns a value: whatever is left in Result.
function CelsiusToF(c: Double): Double;
begin
  Result := c * 9 / 5 + 32;
end;

function WithVat(price: Double): Double;
const
  Rate = 0.21;
begin
  Result := price * (1 + Rate);
end;

function IsLeap(year: Integer): Boolean;
begin
  Result := ((year mod 4 = 0) and (year mod 100 <> 0)) or (year mod 400 = 0);
end;

var
  temp: Integer;
begin
  // A function call goes wherever a value can go.
  for temp := 0 to 3 do
    WriteLn(temp * 10:3, ' C = ', CelsiusToF(temp * 10):5:1, ' F');
  WriteLn('A 20-euro shirt with VAT: ', WithVat(20):0:2);
  WriteLn('Two shirts: ', 2 * WithVat(20):0:2);
  WriteLn('2024 is a leap year? ', IsLeap(2024));
  WriteLn('1900 is a leap year? ', IsLeap(1900));
  WriteLn('2000 is a leap year? ', IsLeap(2000));
end.

program main;

// score is var (the caller's own variable); bonus is just a copy.
procedure AddBonus(var score: Integer; bonus: Integer);
begin
  score := score + bonus;
  bonus := 0;
end;

// var parameters let a procedure hand back several results.
procedure SplitTime(total: Integer; var mins, secs: Integer);
begin
  mins := total div 60;
  secs := total mod 60;
end;

// const: read-only, and the string is not copied.
procedure Show(const player: String; score: Integer);
begin
  WriteLn(player, ': ', score, ' points');
end;

var
  score, bonus, mins, secs: Integer;
begin
  score := 120;
  bonus := 30;
  AddBonus(score, bonus);
  Show('Ana', score);
  WriteLn('Bonus after the call: ', bonus);
  SplitTime(197, mins, secs);
  WriteLn('Lap time: ', mins, ' min ', secs, ' s');
end.

program main;

type
  TProduct = record
    Name: String;
    Price: Double;
    Stock: Integer;
  end;

function MakeProduct(const name: String; price: Double; stock: Integer): TProduct;
begin
  Result.Name := name;
  Result.Price := price;
  Result.Stock := stock;
end;

procedure Show(const p: TProduct);
begin
  WriteLn(p.Name:10, p.Price:8:2, p.Stock:5);
end;

var
  pen, book, diary: TProduct;
begin
  pen := MakeProduct('Pen', 1.20, 50);
  book := MakeProduct('Notebook', 3.75, 12);
  // Assigning a record copies every field.
  diary := book;
  diary.Name := 'Diary';
  Show(pen);
  Show(book);
  Show(diary);
  WriteLn('Stock value: ', pen.Price * pen.Stock + book.Price * book.Stock:0:2);
end.

program main;

type
  TDay = (Mon, Tue, Wed, Thu, Fri, Sat, Sun);  // an enumerated type
  TDays = set of TDay;

var
  day: TDay;
  open: TDays;
  c: Char;
  vowels: Integer;
begin
  day := Wed;
  WriteLn(day, ' is at position ', Ord(day), '; the next day is ', Succ(day));

  // A set holds some of those values, without order or repeats.
  open := [Mon..Fri];
  Include(open, Sat);
  Exclude(open, Wed);
  for day := Mon to Sun do
    if day in open then
      Write(day, ' ');
  WriteLn;
  WriteLn('Open on Sunday? ', Sun in open);
  for day in open * [Sat, Sun] do  // * is the intersection
    WriteLn('Open at the weekend: ', day);

  // Sets of Char make quick character tests.
  vowels := 0;
  for c in 'free pascal compiler' do
    if c in ['a', 'e', 'i', 'o', 'u'] then
      Inc(vowels);
  WriteLn('Vowels: ', vowels);
end.

